from pathlib import Path
root=Path('/mnt/data/fusball_work')
server=root/'backend/server.js'
s=server.read_text()
# Extend ensureCmsTables before closing
needle='''  for (const [key,value] of Object.entries(defaults)) {\n    await pool.query("INSERT IGNORE INTO site_settings(setting_key,setting_value) VALUES (?,?)", [key,value]);\n  }\n};'''
repl='''  for (const [key,value] of Object.entries(defaults)) {\n    await pool.query("INSERT IGNORE INTO site_settings(setting_key,setting_value) VALUES (?,?)", [key,value]);\n  }\n  await pool.query(`CREATE TABLE IF NOT EXISTS blog_posts (\n    id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, excerpt TEXT NULL, url VARCHAR(1000) NOT NULL,\n    image_url VARCHAR(1000) NULL, published TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n  )`);\n  await pool.query(`CREATE TABLE IF NOT EXISTS web_team (\n    id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, role VARCHAR(160) NOT NULL, bio TEXT NULL,\n    photo_url VARCHAR(1000) NULL, instagram_url VARCHAR(1000) NULL, sort_order INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n  )`);\n};'''
assert needle in s
s=s.replace(needle,repl)
# Insert routes after site settings public get
marker='''app.put("/api/admin/site-settings", authenticate, requireRole("admin"), asyncRoute(async (req,res) => {'''
insert='''app.get("/api/blog", asyncRoute(async (_req,res) => {\n  const [rows] = await pool.query(`SELECT id,title,excerpt,url,image_url,published,sort_order,created_at,updated_at FROM blog_posts WHERE published=1 ORDER BY sort_order ASC, created_at DESC`);\n  res.json(rows);\n}));\n\napp.get("/api/team", asyncRoute(async (_req,res) => {\n  const [rows] = await pool.query(`SELECT id,name,role,bio,photo_url,instagram_url,sort_order FROM web_team WHERE active=1 ORDER BY sort_order ASC, id ASC`);\n  res.json(rows);\n}));\n\napp.get("/api/admin/blog", authenticate, requireRole("admin"), asyncRoute(async (_req,res) => {\n  const [rows] = await pool.query(`SELECT * FROM blog_posts ORDER BY sort_order ASC, created_at DESC`); res.json(rows);\n}));\napp.post("/api/admin/blog", authenticate, requireRole("admin"), asyncRoute(async (req,res) => {\n  const title=String(req.body.title||'').trim(), url=String(req.body.url||'').trim();\n  if(!title||!url) return res.status(400).json({message:'Judul dan link blog wajib diisi.'});\n  if(!/^https?:\\/\\//i.test(url)) return res.status(400).json({message:'Link blog harus diawali http:// atau https://.'});\n  const [r]=await pool.query(`INSERT INTO blog_posts(title,excerpt,url,image_url,published,sort_order) VALUES (?,?,?,?,?,?)`,[title,String(req.body.excerpt||'').trim(),url,String(req.body.image_url||'').trim()||null,req.body.published===false?0:1,Number(req.body.sort_order)||0]);\n  res.status(201).json({id:r.insertId,message:'Blog ditambahkan.'});\n}));\napp.put("/api/admin/blog/:id", authenticate, requireRole("admin"), asyncRoute(async (req,res) => {\n  const id=Number(req.params.id), title=String(req.body.title||'').trim(), url=String(req.body.url||'').trim();\n  if(!Number.isInteger(id)||!title||!/^https?:\\/\\//i.test(url)) return res.status(400).json({message:'Data blog belum valid.'});\n  const [r]=await pool.query(`UPDATE blog_posts SET title=?,excerpt=?,url=?,image_url=?,published=?,sort_order=? WHERE id=?`,[title,String(req.body.excerpt||'').trim(),url,String(req.body.image_url||'').trim()||null,req.body.published?1:0,Number(req.body.sort_order)||0,id]);\n  if(!r.affectedRows) return res.status(404).json({message:'Blog tidak ditemukan.'}); res.json({message:'Blog diperbarui.'});\n}));\napp.delete("/api/admin/blog/:id", authenticate, requireRole("admin"), asyncRoute(async (req,res) => { const [r]=await pool.query('DELETE FROM blog_posts WHERE id=?',[Number(req.params.id)]); if(!r.affectedRows)return res.status(404).json({message:'Blog tidak ditemukan.'}); res.json({message:'Blog dihapus.'}); }));\n\napp.get("/api/admin/team", authenticate, requireRole("admin"), asyncRoute(async (_req,res) => { const [rows]=await pool.query('SELECT * FROM web_team ORDER BY sort_order ASC,id ASC'); res.json(rows); }));\napp.post("/api/admin/team", authenticate, requireRole("admin"), asyncRoute(async (req,res) => {\n  const name=String(req.body.name||'').trim(), role=String(req.body.role||'').trim(); if(!name||!role)return res.status(400).json({message:'Nama dan peran wajib diisi.'});\n  const [r]=await pool.query(`INSERT INTO web_team(name,role,bio,photo_url,instagram_url,sort_order,active) VALUES (?,?,?,?,?,?,?)`,[name,role,String(req.body.bio||'').trim(),String(req.body.photo_url||'').trim()||null,String(req.body.instagram_url||'').trim()||null,Number(req.body.sort_order)||0,req.body.active===false?0:1]); res.status(201).json({id:r.insertId,message:'Anggota tim ditambahkan.'});\n}));\napp.put("/api/admin/team/:id", authenticate, requireRole("admin"), asyncRoute(async (req,res) => {\n  const id=Number(req.params.id), name=String(req.body.name||'').trim(), role=String(req.body.role||'').trim(); if(!Number.isInteger(id)||!name||!role)return res.status(400).json({message:'Data tim belum valid.'});\n  const [r]=await pool.query(`UPDATE web_team SET name=?,role=?,bio=?,photo_url=?,instagram_url=?,sort_order=?,active=? WHERE id=?`,[name,role,String(req.body.bio||'').trim(),String(req.body.photo_url||'').trim()||null,String(req.body.instagram_url||'').trim()||null,Number(req.body.sort_order)||0,req.body.active?1:0,id]); if(!r.affectedRows)return res.status(404).json({message:'Anggota tim tidak ditemukan.'}); res.json({message:'Anggota tim diperbarui.'});\n}));\napp.delete("/api/admin/team/:id", authenticate, requireRole("admin"), asyncRoute(async (req,res) => { const [r]=await pool.query('DELETE FROM web_team WHERE id=?',[Number(req.params.id)]); if(!r.affectedRows)return res.status(404).json({message:'Anggota tim tidak ditemukan.'}); res.json({message:'Anggota tim dihapus.'}); }));\n\n'''
assert marker in s
s=s.replace(marker,insert+marker)
server.write_text(s)

# Add schema definitions
schema=root/'database/schema.sql'; ss=schema.read_text(); ss += '''\n\n-- Editorial CMS: external blog links and web design team\nCREATE TABLE IF NOT EXISTS blog_posts (\n  id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, excerpt TEXT NULL, url VARCHAR(1000) NOT NULL,\n  image_url VARCHAR(1000) NULL, published TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS web_team (\n  id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, role VARCHAR(160) NOT NULL, bio TEXT NULL,\n  photo_url VARCHAR(1000) NULL, instagram_url VARCHAR(1000) NULL, sort_order INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n);\n'''; schema.write_text(ss)

# Update navigation in app.js
app=root/'frontend/js/app.js'; a=app.read_text()
a=a.replace('<a href="about.html">Tentang Kami</a><a href="shop.html">Koleksi</a><a href="custom.html">Custom Tim</a><a href="contact.html">Kontak</a>', '<a href="about.html">Tentang Kami</a><a href="shop.html">Koleksi</a><a href="blog.html">Journal</a><a href="custom.html">Custom Tim</a><a href="contact.html">Kontak</a>')
app.write_text(a)

# Add blog/team styling
css=root/'frontend/css/style.css'; c=css.read_text(); c += '''\n\n/* Editorial CMS additions */\n.editorial-list-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.editorial-card{border:1px solid #293235;border-radius:20px;overflow:hidden;background:#101415}.editorial-card-media{aspect-ratio:16/10;background:#0b0f10;overflow:hidden}.editorial-card-media img{width:100%;height:100%;object-fit:cover}.editorial-card-body{padding:20px}.editorial-card-body h3{margin:6px 0 9px;font-size:22px;letter-spacing:-.04em}.editorial-card-body p{color:#8a9498;line-height:1.6}.team-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.team-card{border:1px solid #293235;border-radius:20px;overflow:hidden;background:#101415}.team-photo{aspect-ratio:4/3;background:#0b0f10}.team-photo img{width:100%;height:100%;object-fit:cover}.team-body{padding:18px}.team-body h3{margin:0 0 5px;font-size:21px}.team-role{font-size:10px;color:var(--accent);font-weight:900;letter-spacing:.1em;text-transform:uppercase}.team-body p{color:#8a9498;line-height:1.55}.journal-hero{padding:110px 0 70px}.journal-hero h1{font-size:clamp(52px,8vw,108px);letter-spacing:-.08em;line-height:.9;margin:10px 0 20px}.journal-link{display:flex;justify-content:space-between;gap:20px;align-items:end;color:inherit;text-decoration:none}.journal-link:hover .journal-title{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:5px}@media(max-width:900px){.editorial-list-grid,.team-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.editorial-list-grid,.team-grid{grid-template-columns:1fr}.journal-hero{padding-top:70px}}\n'''; css.write_text(c)

# Create blog page
(root/'frontend/blog.html').write_text('''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Fusball.id Journal — cerita, football culture, desain, dan update koleksi."><title>Journal — Fusball.id</title><link rel="icon" href="assets/images/logo-mark.svg"><link rel="stylesheet" href="css/style.css"></head><body data-page="blog"><div id="site-header"></div><main><section class="journal-hero shell"><span class="kicker">FUSBALL.ID / JOURNAL</span><h1>Stories beyond<br><em>the shirt.</em></h1><p class="detail-desc" style="max-width:680px">Kumpulan artikel, referensi, dan cerita yang dipilih tim Fusball.id. Semua artikel diarahkan ke sumber asli, karena mengarang blog sendiri sudah cukup dilakukan internet.</p></section><section class="section shell"><div class="section-head-v9"><div><span class="kicker">LATEST STORIES</span><h2>Football culture, design & identity.</h2></div></div><div id="blog-grid" class="editorial-list-grid"></div></section></main><div id="site-footer"></div><script src="js/api.js"></script><script src="js/auth.js"></script><script src="js/app.js"></script><script>document.addEventListener('DOMContentLoaded',async()=>{const root=document.getElementById('blog-grid');try{const rows=await apiGet('/blog');root.innerHTML=rows.length?rows.map(x=>`<article class="editorial-card"><div class="editorial-card-media">${x.image_url?`<img src="${escapeHtml(x.image_url)}" alt="">`:'<div style="height:100%;display:grid;place-items:center;color:#667174;font-size:10px;letter-spacing:.12em">FUSBALL JOURNAL</div>'}</div><div class="editorial-card-body"><span class="kicker">JOURNAL</span><h3 class="journal-title">${escapeHtml(x.title)}</h3><p>${escapeHtml(x.excerpt||'Baca artikel selengkapnya melalui sumber asli.')}</p><a class="text-link" href="${escapeHtml(x.url)}" target="_blank" rel="noopener noreferrer">Baca artikel ↗</a></div></article>`).join(''):'<div class="empty-v10" style="grid-column:1/-1">Belum ada artikel. Tambahkan link dari Control Room.</div>'}catch(e){root.innerHTML='<div class="empty-v10" style="grid-column:1/-1">Journal belum dapat dimuat.</div>'}});function escapeHtml(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}</script></body></html>''')

# Add team section to about before final CTA
about=root/'frontend/about.html'; ab=about.read_text(); marker='<section class="final-cta-v9 shell reveal-on-scroll">'
team='''<section class="section shell reveal-on-scroll"><div class="section-head-v9"><div><span class="kicker">THE TEAM</span><h2>Orang di balik pengalaman web ini.</h2><p class="detail-desc">Tim perancang web yang mengembangkan dan menjaga pengalaman digital Fusball.id.</p></div></div><div id="team-grid" class="team-grid"></div></section>\n'''
ab=ab.replace(marker,team+marker)
ab=ab.replace('</script></body></html>','''try{const team=await apiGet('/team');const root=document.getElementById('team-grid');root.innerHTML=team.length?team.map(x=>`<article class="team-card"><div class="team-photo">${x.photo_url?`<img src="${escapeHtml(x.photo_url)}" alt="${escapeHtml(x.name)}">`:'<div style="height:100%;display:grid;place-items:center;color:#667174;font-size:10px;letter-spacing:.12em">TEAM MEMBER</div>'}</div><div class="team-body"><span class="team-role">${escapeHtml(x.role)}</span><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.bio||'')}</p>${x.instagram_url?`<a class="text-link" href="${escapeHtml(x.instagram_url)}" target="_blank" rel="noopener">Instagram ↗</a>`:''}</div></article>`).join(''):'<div class="empty-v10" style="grid-column:1/-1">Profil tim belum ditambahkan.</div>'}catch(e){}function escapeHtml(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}</script></body></html>''')
about.write_text(ab)

